function cvEsc(cvValue){return String(cvValue==null?'':cvValue).replace(/[&<>"']/g,cvChar=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[cvChar]));}
function cvLength(cvValue){return Array.from(cvValue.trim()).length;}
function cvValid(cvValue,cvMin,cvMax){const cvN=cvLength(cvValue);return cvN>=cvMin&&cvN<=cvMax;}
function cvBtn(cvText,cvAction,cvKind='',cvDisabled=false){return `<button type="button" class="btn ${cvKind}" onclick="${cvEsc(cvAction)}" ${cvDisabled?'disabled':''}>${cvText}</button>`;}
function cvLink(cvText,cvRoute){return `<a class="btn ghost sm" href="#/${cvRoute}">${cvText}</a>`;}
function cvKv(cvRows){return `<dl class="kv">${cvRows.map(cvRow=>`<dt>${cvRow[0]}</dt><dd>${cvRow[1]}</dd>`).join('')}</dl>`;}
function cvTable(cvHeaders,cvRows){return `<div class="table-wrap"><table><thead><tr>${cvHeaders.map(cvH=>`<th>${cvH}</th>`).join('')}</tr></thead><tbody>${cvRows.map(cvRow=>`<tr>${cvRow.map(cvCell=>`<td>${cvCell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function cvArea(cvLabel,cvValue,cvAction,cvMax=2000,cvDisabled=false){return `<label class="stack">${cvLabel}<textarea rows="3" maxlength="${cvMax}" style="${cvStyle}" oninput="${cvEsc(cvAction)}" ${cvDisabled?'disabled':''}>${cvEsc(cvValue)}</textarea></label>`;}
function cvFrame(cvTitle,cvBody){return head('Contoso · 账单中心',cvTitle,'你以 Lee 身份查看 · 可签认')+`<div class="stack">${cvBody}<p class="muted xs">原型演示：提交仅保存在本次浏览器会话，刷新后恢复样例。</p></div>`;}
function cvMissing(){return cvFrame('内容不可用',card('访问范围','<div class="empty">未找到你可查看的内容。</div>')+card('当前身份',cvKv([['账户','Contoso'],['联系人','Lee']]))+card('联系对接人',cvLink('在共享频道询问','chat/contoso')));}
function cvProjectAllowed(cvArg){return !cvArg||cvArg==='p1';}
function cvRefresh(){route();}
function cvOffline(){return navigator.onLine===false;}
function cvTodo(){return cvFrame('待办',card('待你签认',cvKv([['项目','账单中心'],['需求确认单','BL-7 v1'],['状态',cvState.signed?'已签认':'待你签认']])+cvLink('查看需求确认单','baseline/p1'))+card('待你确认的变更',cvKv([['变更','IN-2042'],['工期变化','+4 天'],['费用变化','+¥1,200'],['状态',cvState.decision?'你已决定，等待团队处理':'待你确认']])+cvLink('查看变更影响','change/IN-2042'))+card('待你验收的交付',cvKv([['交付包','BIL#3'],['交付物','3 项'],['状态',cvState.receipt?cvState.receipt.result:'待你验收']])+cvLink('核对并验收','delivery/D-3')));}
function cvMilestoneBlock(){return cvTable(['里程碑','预计日期','状态'],cvMilestones.map((cvM,cvI)=>[cvM[0],cvM[1],cvI===0&&cvState.signed?'已签认':cvM[2]]));}
function cvProject(cvArg){if(!cvProjectAllowed(cvArg))return cvMissing();return cvFrame('项目概览',card('里程碑时间线',cvMilestoneBlock())+card('最近进度更新','<div class="decision-card stack"><b>导出能力 · 进行中</b><p>导出能力已完成 4 / 6 项，字段排序与权限口径仍在核对。</p>'+cvKv([['预计日期','2026-10-27'],['发布人','Morgan'],['发布时间','2026-10-12 10:00'],['发布状态','经团队批准后发出']])+'</div><div class="note info">新增字段方案的工期与费用需由你确认，当前承诺不会因进度卡自动改变。</div>')+card('对接人',cvKv([['对接人','Morgan'],['负责事项','范围、日期、价格与承诺'],['你的账户','Contoso · Lee'],['沟通频道','账单中心共享频道 · 甲方在此频道']])+cvLink('去共享频道','chat/contoso')));}
function cvBaseline(cvArg){if(!cvProjectAllowed(cvArg))return cvMissing();return cvFrame('需求确认单',card('BL-7 v1 · 账单中心二期',cvKv([['状态',cvState.signed?'已签认 · 已成为基线':'待你签认'],['来源','账单中心二期需求说明书.docx'],['摘要','3 个阶段 · 5 个里程碑 · 14 条需求项 · 21 条验收标准'],['签认人','Lee · Contoso']]))+['需求与口径','导出与权限','交付与说明'].map((cvPhase,cvP)=>card('阶段 '+(cvP+1)+' · '+cvPhase,cvRequirements.filter(cvItem=>cvItem[2]===cvP).map(cvItem=>`<div class="stack" style="margin-bottom:16px"><div class="row wrap"><b class="grow">${cvItem[0]}</b><span class="badge b-info">优先级：${cvItem[1]}</span></div><details><summary>展开验收标准 · ${cvItem[3].length} 条</summary>${cvItem[3].map(cvC=>`<p class="small">${cvC}</p>`).join('')}</details>${cvLink('有疑问','chat/contoso')}</div>`).join(''))).join('')+card('里程碑',cvMilestoneBlock())+card('范围外','<p>本期不包含自动报价。</p><p>本期不包含多币种自动换算。</p>')+card('版本历史',cvTable(['版本','日期','说明'],[['v1','2026-10-12','按需求说明书整理，待你签认']])+ (cvState.signed?`<p>你于 ${cvEsc(cvState.signed)} 签认 v1；后续改动须生成新版本。</p>`:''))+card('签认此版本',cvState.signed?'<div class="note ok">你已签认 BL-7 v1，此版本只读。</div>':`<label class="row"><input type="checkbox" ${cvState.read?'checked':''} onchange="cvState.read=this.checked;cvValidate()">我已阅读</label><p class="note info">签认后此版本成为基线；瀑布与清单需求签认后才开始。后续改动走变更。</p><button id="cv-sign" class="btn primary" ${!cvState.read||cvOffline()?'disabled':''} onclick="cvSign()">签认此版本</button><p class="muted small">勾选「我已阅读」且连接正常后可签认。</p>`));}
function cvSign(){if(cvState.signed||!cvState.read||cvOffline())return;cvState.signed=new Date().toLocaleString('zh-CN');cvRefresh();toast('已签认 BL-7 v1（原型演示）');}
function cvChangeStatus(cvC){return cvC.id==='IN-2042'&&cvState.decision?'评估中':cvC.state;}
function cvChangesPage(cvArg){if(!cvProjectAllowed(cvArg))return cvMissing();return cvFrame('变更',card('变更列表',cvTable(['变更','内容','状态'],cvChanges.map(cvC=>[`<a href="#/change/${cvC.id}">${cvC.id}</a>`,cvC.title,cvChangeStatus(cvC)])))+card('当前待确认方案',cvKv([['变更','IN-2042'],['工期变化','+4 天'],['费用变化','+¥1,200'],['新的预计日期','2026-10-27']]))+card('变更规则','<p>超出约定的工期与费用先请你确认。容差内变更会告知你结果与影响。</p><p>你不同意时原需求保持不变；团队会与你沟通调整方案或撤回变更。</p>'));}
function cvChange(cvArg){const cvC=cvChanges.find(cvItem=>cvItem.id===(cvArg||'IN-2042'));if(!cvC)return cvMissing();const cvPending=cvC.id==='IN-2042'&&!cvState.decision;return cvFrame('变更影响确认',card('变更内容',cvKv([['变更',cvC.id],['状态',cvChangeStatus(cvC)],['内容',cvC.description]])+(cvC.diff||[]).map(cvD=>`<p>${cvD}</p>`).join(''))+card('对已完成部分的影响',cvC.days==null?'<div class="empty">团队评估中，工期与费用尚未确定。</div>':cvKv([['已完成的部分',cvC.id==='IN-2042'?'1 项已完成的内容需要按新要求调整':'按原计划交付'],['工期变化',cvC.days?'+'+cvC.days+' 天':'无变化'],['新的预计日期',cvC.date],['费用变化',cvC.price?'增加 ¥'+cvC.price.toLocaleString('zh-CN'):'无变化']])+'<div class="note info">范围、日期与费用由对接人确认；你的决定不自动修改需求版本。</div>')+card('你的决定',cvPending?`<div class="stack"><label class="row"><input type="checkbox" ${cvState.changeRead?'checked':''} onchange="cvState.changeRead=this.checked;cvValidate()">我已阅读上述影响</label><button id="cv-agree" class="btn primary" ${!cvState.changeRead||cvOffline()?'disabled':''} onclick="cvDecide('同意')">同意并继续</button><p class="muted small">阅读影响并勾选后可同意；离线时不可提交。</p>${cvArea('不同意的理由（必填，10–2000 字）',cvState.changeReason,'cvState.changeReason=this.value;cvValidate()')}<button id="cv-disagree" class="btn" ${!cvValid(cvState.changeReason,10,2000)||cvOffline()?'disabled':''} onclick="cvDecide('不同意')">不同意</button><p class="muted small">不同意须填写 10–2000 字理由。原需求保持不变，团队将与你沟通。</p><p class="small">7 天后提醒你，14 天后提醒团队；不会自动替你决定。本次确认不需重新认证。</p></div>`:cvState.decision&&cvC.id==='IN-2042'?cvKv([['你的决定',cvState.decision.result],['理由',cvEsc(cvState.decision.reason)||'无'],['决定时间',cvState.decision.time],['后续','等待团队处理，原需求版本保持不变']]):cvKv([['状态',cvC.state],['说明',cvC.reason||'当前没有待你确认的请求。']])));}
function cvDecide(cvResult){if(cvState.decision||cvOffline()||cvResult==='同意'&&!cvState.changeRead||cvResult==='不同意'&&!cvValid(cvState.changeReason,10,2000))return;const cvReason=cvResult==='不同意'?cvState.changeReason.trim():'';openModal(`<div class="stack" style="padding:24px"><h3>确认${cvResult}本次变更</h3>${cvKv([['确认轮次','第 1 轮'],['工期','+4 天 · 预计 2026-10-27'],['费用','+¥1,200'],['理由',cvEsc(cvReason)||'无']])}<p>同意后等待团队应用新版本；不同意时原需求保持不变。不需重新认证。</p>${cvBtn('返回核对','closeModal()')}${cvBtn('确认提交',`cvCommitChange('${cvResult}',1)`,'primary')}</div>`);}
function cvCommitChange(cvResult,cvRound){if(cvState.decision||cvOffline()||cvRound!==cvChanges[0].round)return toast('确认请求已失效，请重新查看');if(cvResult==='同意'&&!cvState.changeRead||cvResult==='不同意'&&!cvValid(cvState.changeReason,10,2000))return;cvState.decision={result:cvResult,reason:cvResult==='不同意'?cvState.changeReason.trim():'',time:new Date().toLocaleString('zh-CN'),round:cvRound};closeModal();cvRefresh();toast('你的决定已记录（原型演示）');}
function cvDeliveries(cvArg){if(!cvProjectAllowed(cvArg))return cvMissing();return cvFrame('交付与验收',card('交付列表',cvTable(['交付包','日期','内容','状态'],[[`<a href="#/delivery/D-3">BIL#3</a>`,'2026-10-12','CSV 导出、字段排序、失败重试提示',cvState.receipt?cvState.receipt.result:'待你验收']]))+card('交付清单',cvKv([['清单版本','第 3 版'],['条目','3 项'],['接收人','Lee · Contoso']]))+card('验收说明','<p>请逐项接受或不接受；不接受须填写类别与原因，可引用该项批注。</p><p>提交后回执不可修改，已接受部分保留结果，不接受部分由团队继续处理。</p>'));}
function cvPreviewChips(){return `<div class="row wrap"><span class="small">状态预览</span>${['正常','异常','空'].map(cvMode=>`<button type="button" class="chip ${cvState.preview===cvMode?'on':''}" aria-pressed="${cvState.preview===cvMode}" onclick="cvState.preview='${cvMode}';cvRefresh()">${cvMode}</button>`).join('')}</div>`;}
function cvOpen(cvIndex){cvState.open=cvState.open===cvIndex?null:cvIndex;cvRefresh();}
function cvAnchor(cvIndex,cvPosition){if(cvState.receipt||cvState.preview!=='正常')return;const cvF=cvFiles[cvIndex];cvState.anchor[cvIndex]={kind:cvF.kind,version:cvF.version,file:cvF.name,...cvPosition};cvRefresh();}
function cvPointer(cvEvent,cvPhase){if(cvState.receipt)return;const cvBounds=cvEvent.currentTarget.getBoundingClientRect(),cvPoint={x:Math.max(0,Math.min(100,(cvEvent.clientX-cvBounds.left)/cvBounds.width*100)),y:Math.max(0,Math.min(100,(cvEvent.clientY-cvBounds.top)/cvBounds.height*100))};if(cvPhase==='start'){if(cvEvent.button!==0)return;cvState.drag={...cvPoint,id:cvEvent.pointerId,width:Math.round(cvBounds.width),height:Math.round(cvBounds.height)};cvEvent.currentTarget.setPointerCapture(cvEvent.pointerId);return;}const cvFrom=cvState.drag;cvState.drag=null;if(!cvFrom||cvFrom.id!==cvEvent.pointerId)return;const cvRect={x:Math.round(Math.min(cvPoint.x,cvFrom.x)),y:Math.round(Math.min(cvPoint.y,cvFrom.y)),width:Math.round(Math.abs(cvPoint.x-cvFrom.x)),height:Math.round(Math.abs(cvPoint.y-cvFrom.y))};if(cvRect.width<2||cvRect.height<2)return toast('请框选更大的截图区域');cvAnchor(2,{selector:'#cv-shot',rect:cvRect,viewport:{width:cvFrom.width,height:cvFrom.height},excerpt:`截图区域：左 ${cvRect.x}%，上 ${cvRect.y}%，宽 ${cvRect.width}%，高 ${cvRect.height}%`});}
function cvRegion(){const cvEl=document.getElementById('cv-shot');if(!cvEl)return;cvAnchor(2,{selector:'#cv-shot',rect:{x:12,y:35,width:76,height:50},viewport:{width:Math.round(cvEl.clientWidth),height:Math.round(cvEl.clientHeight)},excerpt:'失败提示与重试入口区域'});}
function cvFileContent(cvIndex,cvAnnotate){const cvF=cvFiles[cvIndex];if(cvIndex===0)return cvTable(['行号','账期','客户','税前金额','税额','含税金额',...(cvAnnotate?['批注']:[])],cvF.rows.map((cvRow,cvR)=>[cvR+2,...cvRow,...(cvAnnotate?[cvBtn('批注此行',`cvAnchor(0,{row:${cvR+2},excerpt:'第 ${cvR+2} 行 · ${cvRow[1]}'})`,'sm')]:[])]));if(cvIndex===1)return cvF.paragraphs.map((cvText,cvP)=>`<div class="bubble"><p>${cvText}</p>${cvAnnotate?cvBtn('批注此段',`cvAnchor(1,{paragraph:${cvP+1},quote:${JSON.stringify(cvText)},excerpt:'第 ${cvP+1} 段'})`,'sm'):''}</div>`).join('');const cvRect=cvState.anchor[2]?.rect;return `<div id="cv-shot" style="position:relative;min-height:240px;box-sizing:border-box;padding:24px;border:1px solid var(--border);touch-action:none;user-select:none" ${cvAnnotate?'onpointerdown="cvPointer(event,\'start\')" onpointerup="cvPointer(event,\'end\')" onpointercancel="cvState.drag=null"':''}><b>账单导出</b><div class="sep"></div><div class="note warn">导出未成功，请稍后重试。</div><span class="badge b-primary">重新导出</span>${cvRect?`<div aria-hidden="true" style="position:absolute;pointer-events:none;left:${cvRect.x}%;top:${cvRect.y}%;width:${cvRect.width}%;height:${cvRect.height}%;border:2px dashed var(--primary)"></div>`:''}</div><p class="muted xs">截图内容为原型示意。</p>${cvAnnotate?cvBtn('选择失败提示与重试区域','cvRegion()','sm'):''}`;}
function cvComments(cvIndex,cvPick=false,cvSnapshot){return (cvSnapshot||cvState.comments[cvIndex]).map(cvC=>`<div class="bubble stack"><b>${cvEsc(cvC.anchor.excerpt)}</b><p>${cvEsc(cvC.body)}</p><span class="muted xs">你 · ${cvEsc(cvC.time)} · ${cvEsc(cvC.anchor.file)} · ${cvEsc(cvC.anchor.version)}</span>${cvC.replies.map(cvReply=>`<p class="small">你：${cvEsc(cvReply)}</p>`).join('')}${cvPick?`<label class="row"><input type="checkbox" ${cvState.refs[cvIndex].includes(cvC.id)?'checked':''} onchange="cvReference(${cvIndex},${cvC.id},this.checked)">引用此批注</label>`:!cvState.receipt?cvBtn('回复',`cvReply(${cvIndex},${cvC.id})`,'sm'):cvBtn('查看引用位置',`cvLocate(${cvIndex},${cvC.id})`,'sm')}</div>`).join('')||'<div class="empty">暂无批注。选择文件中的位置后可填写批注。</div>';}
function cvLocate(cvIndex,cvId){const cvC=cvState.receipt?.items[cvIndex].comments.find(cvItem=>cvItem.id===cvId);if(!cvC)return;cvState.anchor[cvIndex]=JSON.parse(JSON.stringify(cvC.anchor));openDrawer(`<div class="stack" style="padding:24px">${cvBtn('关闭','closeDrawer()','ghost sm')}${card('引用位置 · '+cvEsc(cvC.anchor.file),cvKv([['文件版本',cvEsc(cvC.anchor.version)],['锚点位置',cvEsc(cvC.anchor.excerpt)],['批注内容',cvEsc(cvC.body)]]))+card('原版本内容',cvFileContent(cvIndex,false))}</div>`);}
function cvViewer(cvIndex){if(cvState.open!==cvIndex)return '';const cvF=cvFiles[cvIndex],cvA=cvState.anchor[cvIndex];if(cvState.preview!=='正常')return cvPreviewChips()+(cvState.preview==='空'?'<div class="empty">暂无可预览内容，不能创建批注。</div>':'<div class="note danger">文件预览失败，不能创建批注。切回正常状态后重试。</div>');return `<div class="stack">${cvPreviewChips()}${cvKv([['文件',cvF.name],['版本',cvF.version]])}${cvFileContent(cvIndex,!cvState.receipt)}${!cvState.receipt?`<p>当前锚点：${cvA?cvEsc(cvA.excerpt):'尚未选择'}</p>${cvArea('批注内容（1–2000 字）',cvState.drafts[cvIndex]||'',`cvState.drafts[${cvIndex}]=this.value;cvValidate()`)}<button type="button" id="cv-post-${cvIndex}" class="btn primary" ${!cvCanPost(cvIndex)?'disabled':''} onclick="cvPost(${cvIndex})">保存批注</button><p class="muted xs">选择锚点、填写 1–2000 字且连接正常后可保存；批注绑定此文件版本。</p>`:''}<b>批注线程</b>${cvComments(cvIndex)}</div>`;}
function cvCanPost(cvIndex){return !cvState.receipt&&cvState.preview==='正常'&&!cvOffline()&&!!cvState.anchor[cvIndex]&&cvState.anchor[cvIndex].version===cvFiles[cvIndex].version&&cvValid(cvState.drafts[cvIndex]||'',1,2000)&&cvState.sequence<200;}
function cvPost(cvIndex){if(!cvCanPost(cvIndex))return toast('当前不能保存批注；请检查锚点、版本、字数、连接与每日 200 条限额');cvState.comments[cvIndex].push({id:++cvState.sequence,anchor:JSON.parse(JSON.stringify(cvState.anchor[cvIndex])),body:cvState.drafts[cvIndex].trim(),time:new Date().toLocaleString('zh-CN'),replies:[]});cvState.drafts[cvIndex]='';cvRefresh();}
function cvReply(cvIndex,cvId){if(cvState.receipt||cvOffline()||cvState.preview!=='正常')return toast('已回执、离线或预览异常时不能回复');openModal(`<div class="stack" style="padding:24px"><h3>回复批注</h3><label class="stack">回复内容（1–2000 字）<textarea id="cv-reply" rows="3" maxlength="2000" style="${cvStyle}" oninput="document.getElementById('cv-reply-send').disabled=!cvValid(this.value,1,2000)"></textarea></label><p class="muted small">填写内容后可提交；每线程最多 200 条，每交付每天最多 200 条。</p>${cvBtn('关闭','closeModal()')}<button type="button" id="cv-reply-send" class="btn primary" disabled onclick="cvSaveReply(${cvIndex},${cvId})">提交回复</button></div>`);}
function cvSaveReply(cvIndex,cvId){const cvC=cvState.comments[cvIndex].find(cvItem=>cvItem.id===cvId),cvBody=document.getElementById('cv-reply')?.value||'';if(!cvC||cvState.receipt||cvOffline()||cvState.preview!=='正常'||!cvValid(cvBody,1,2000)||cvC.replies.length>=199||cvState.sequence>=200)return toast('回复不可用：检查字数、连接与批注限额');cvC.replies.push(cvBody.trim());cvState.sequence++;closeModal();cvRefresh();}
function cvChoose(cvIndex,cvChoice){if(cvState.receipt)return;cvState.choices[cvIndex]=cvChoice;if(cvChoice==='接受')cvState.refs[cvIndex]=[];cvRefresh();}
function cvReference(cvIndex,cvId,cvChecked){if(cvState.receipt||cvState.choices[cvIndex]!=='不接受'||!cvState.comments[cvIndex].some(cvC=>cvC.id===cvId))return;const cvRefs=cvState.refs[cvIndex];if(cvChecked&&!cvRefs.includes(cvId)){if(cvRefs.length>=20){cvRefresh();return toast('每项最多引用 20 条批注');}cvRefs.push(cvId);}else if(!cvChecked)cvState.refs[cvIndex]=cvRefs.filter(cvValue=>cvValue!==cvId);cvValidate();}
function cvAcceptReady(){return !cvState.receipt&&!cvOffline()&&cvState.ack&&cvValid(cvState.signer,1,100)&&cvLength(cvState.note)<=2000&&cvFiles.every((cvF,cvIndex)=>cvState.choices[cvIndex]==='接受'||cvState.choices[cvIndex]==='不接受'&&cvState.categories[cvIndex]&&cvValid(cvState.reasons[cvIndex],10,2000));}
function cvDelivery(cvArg){if(cvArg&&cvArg!=='D-3')return cvMissing();let cvBody=card('BIL#3 · 第 3 次交付',cvKv([['交付日期','2026-10-12'],['交付清单','3 项'],['证据摘要','CSV 格式、列顺序与失败提示的交付文件'],['清单指纹',`<code class="mono" style="overflow-wrap:anywhere">${cvManifest}</code>`]])+'<p class="muted xs">此指纹为原型示例，不用于真实验证。</p>');if(cvState.receipt){const cvR=cvState.receipt;return cvFrame('交付验收',cvBody+card('验收回执（只读）',cvKv([['验收结果',cvR.result],['签署人',cvEsc(cvR.signer)],['签署时间',cvR.time],['整体备注',cvEsc(cvR.note)||'无']])+cvR.items.map((cvItem,cvIndex)=>`<div class="bubble stack"><b>${cvFiles[cvIndex].title} · ${cvItem.choice}</b>${cvItem.choice==='不接受'?`<p>${cvEsc(cvItem.category)}：${cvEsc(cvItem.reason)}</p><b>引用批注 ${cvItem.comments.length} 条</b>${cvComments(cvIndex,false,cvItem.comments)}`:''}</div>`).join(''))+card('后续处理','<p>已接受部分保留结果；不接受部分由团队继续处理。此回执不可修改。</p>'));}
 cvBody+=card('逐项核对',cvBtn('全部接受',"cvState.choices=['接受','接受','接受'];cvState.refs=[[],[],[]];cvRefresh()")+'<p class="small">你可以部分验收。查看并批注不会丢失已填写的选择。</p>')+cvFiles.map((cvF,cvIndex)=>card(cvF.title,`<div class="stack"><p>验收标准：${cvF.standard}</p>${cvBtn('查看并批注',`cvOpen(${cvIndex})`)}${cvViewer(cvIndex)}<div class="row wrap">${['接受','不接受'].map(cvChoice=>`<button type="button" class="chip ${cvState.choices[cvIndex]===cvChoice?'on':''}" aria-pressed="${cvState.choices[cvIndex]===cvChoice}" onclick="cvChoose(${cvIndex},'${cvChoice}')">${cvChoice}</button>`).join('')}</div>${cvState.choices[cvIndex]==='不接受'?`<label class="stack">不接受类别（必填）<select style="${cvStyle}" onchange="cvState.categories[${cvIndex}]=this.value;cvValidate()"><option value="">请选择</option>${['功能缺陷','需求不符','样式','性能','安全','其他'].map(cvCat=>`<option ${cvState.categories[cvIndex]===cvCat?'selected':''}>${cvCat}</option>`).join('')}</select></label>${cvArea('不接受原因（必填，10–2000 字）',cvState.reasons[cvIndex],`cvState.reasons[${cvIndex}]=this.value;cvValidate()`)}<b>引用批注（可选，最多 20 条）</b>${cvComments(cvIndex,true)}<p class="muted small">引用批注不能替代类别和原因。</p>`:''}</div>`)).join('')+card('签署与确认',`<div class="stack"><label class="stack">签署人姓名（1–100 字）<input maxlength="100" style="${cvStyle}" value="${cvEsc(cvState.signer)}" oninput="cvState.signer=this.value;cvValidate()"></label><label class="row"><input type="checkbox" ${cvState.ack?'checked':''} onchange="cvState.ack=this.checked;cvValidate()">我已核对以上交付内容和清单指纹，提交后不可修改</label>${cvArea('整体备注（可选，最多 2000 字）',cvState.note,'cvState.note=this.value;cvValidate()')}<p id="cv-accept-hint" class="muted small" role="status">逐项选择、补齐拒收信息、填写姓名并确认清单后可提交；离线时不可提交。</p><button id="cv-accept" class="btn primary" ${cvAcceptReady()?'':'disabled'} onclick="cvAccept()">提交验收</button></div>`);return cvFrame('交付验收',cvBody);}
function cvAccept(){if(!cvAcceptReady())return;const cvYes=cvState.choices.filter(cvChoice=>cvChoice==='接受').length;openModal(`<div class="stack" style="padding:24px"><h3>确认提交验收</h3><p>将接受 ${cvYes} 项、不接受 ${3-cvYes} 项。</p><div class="note warn">回执提交后不可修改。不接受部分由团队继续处理。</div>${cvBtn('返回核对','closeModal()')}${cvBtn('确认提交',`cvCommitAcceptance('${cvManifest}')`,'primary')}</div>`);}
function cvCommitAcceptance(cvFingerprint){if(cvFingerprint!==cvManifest)return toast('交付内容已更新，请重新核对');if(!cvAcceptReady())return;const cvYes=cvState.choices.filter(cvChoice=>cvChoice==='接受').length;cvState.receipt={result:cvYes===3?'全部验收':cvYes===0?'全部不接受':'部分验收',signer:cvState.signer.trim(),time:new Date().toLocaleString('zh-CN'),note:cvState.note.trim(),manifest:cvFingerprint,items:cvFiles.map((cvF,cvIndex)=>({choice:cvState.choices[cvIndex],category:cvState.categories[cvIndex],reason:cvState.reasons[cvIndex].trim(),comments:cvState.choices[cvIndex]==='不接受'?JSON.parse(JSON.stringify(cvState.comments[cvIndex].filter(cvC=>cvState.refs[cvIndex].includes(cvC.id)))):[]}))};closeModal();cvRefresh();toast('验收回执已记录（原型演示）');}
function cvPreviews(cvArg){if(!cvProjectAllowed(cvArg))return cvMissing();return cvFrame('预览与产物',card('面向你的产物',cvPreviewChips()+(cvState.preview==='异常'?'<div class="note danger">产物列表暂时无法加载。切回正常状态后重试。</div>':cvState.preview==='空'?'<div class="empty">暂无已进入交付包的产物。</div>':cvTable(['产物','文件版本','所属交付','查看'],cvFiles.map((cvF,cvIndex)=>[cvF.name,cvF.version,'BIL#3',cvBtn(cvState.open===cvIndex?'收起':'同页查看',`cvOpen(${cvIndex})`,'sm')]))))+card('产物查看',cvState.preview==='正常'&&cvState.open!==null?cvKv([['文件',cvFiles[cvState.open].name],['版本',cvFiles[cvState.open].version]])+cvFileContent(cvState.open,false):'<div class="empty">选择上方产物，在此查看内容。</div>')+card('交付范围',cvKv([['来源','已进入 BIL#3 交付包的面向甲方文件'],['预览性质','只读查看'],['验收','预览不代表验收通过']])));}
function cvIssueReady(){const cvD=cvState.issue;return !cvOffline()&&cvValid(cvD.title,1,200)&&cvValid(cvD.description,1,20000)&&!cvD.error;}
function cvIssueFiles(cvInput){const cvFilesChosen=Array.from(cvInput.files),cvBad=cvFilesChosen.some(cvF=>cvF.size>25*1024*1024||/\.(exe|com|bat|cmd|ps1|sh|js|msi)$/i.test(cvF.name));cvState.issue.error=cvBad?'附件超限或属于不支持的可执行文件；请重新选择。':cvFilesChosen.length>10||cvFilesChosen.reduce((cvN,cvF)=>cvN+cvF.size,0)>50*1024*1024?'最多 10 个附件，总计不超过 50 MB。':'';cvState.issue.files=cvFilesChosen.map(cvF=>({name:cvF.name,size:cvF.size}));const cvHost=document.getElementById('cv-files');cvHost.textContent=cvState.issue.error||cvState.issue.files.map(cvF=>cvF.name+' · 已选择').join('、')||'尚未添加附件';cvValidate();}
function cvFeedback(cvArg){if(!cvProjectAllowed(cvArg))return cvMissing();const cvD=cvState.issue;return cvFrame('问题反馈',card('提交问题',`<form class="stack" onsubmit="event.preventDefault();cvSubmitIssue()"><label class="stack">标题（必填，1–200 字）<input maxlength="200" required style="${cvStyle}" value="${cvEsc(cvD.title)}" oninput="cvState.issue.title=this.value;cvValidate()"></label>${cvArea('描述（必填，1–20,000 字）',cvD.description,'cvState.issue.description=this.value;cvValidate()',20000)}<label class="stack">严重程度建议<select style="${cvStyle}" onchange="cvState.issue.severity=this.value">${['轻微','一般','严重','紧急'].map(cvSeverity=>`<option ${cvD.severity===cvSeverity?'selected':''}>${cvSeverity}</option>`).join('')}</select></label><label class="stack">附件<input type="file" multiple onchange="cvIssueFiles(this)"></label><p id="cv-files" class="muted small" role="status">${cvEsc(cvD.error||cvD.files.map(cvF=>cvF.name).join('、')||'尚未添加附件')}</p><p class="muted xs">最多 10 个附件，单个 25 MB，总计 50 MB；原型仅模拟附件登记与扫描，不上传真实文件。</p><button id="cv-issue" class="btn primary" ${cvIssueReady()?'':'disabled'}>提交问题</button><p class="muted small">填写标题和描述、附件符合限制且连接正常后可提交。</p></form>`)+card('你的问题',cvTable(['标题','严重程度建议','状态'],[...cvState.feedback.map(cvF=>[cvEsc(cvF.title),cvF.severity,cvF.status]),['账单金额显示需补充说明','一般','已收到'],['导出等待提示不明确','轻微','处理中'],['使用说明链接不可用','一般','已解决']])+cvState.feedback.map(cvF=>`<details><summary>${cvEsc(cvF.title)} · 查看反馈</summary><p style="white-space:pre-wrap">${cvEsc(cvF.description)}</p><p>附件：${cvEsc(cvF.files.map(cvFile=>cvFile.name).join('、')||'无')}</p><p class="muted xs">你于 ${cvEsc(cvF.time)} 提交 · 附件扫描通过（原型模拟）</p></details>`).join(''))+card('反馈与沟通',cvKv([['你可查看的状态','已收到 / 处理中 / 已解决'],['严重程度','你的建议，由团队确认'],['对接人','Morgan']])+cvLink('去共享频道补充信息','chat/contoso')));}
function cvSubmitIssue(){if(!cvIssueReady())return;cvState.feedback.unshift({...cvState.issue,files:cvState.issue.files.map(cvF=>({...cvF})),status:'已收到',time:new Date().toLocaleString('zh-CN')});cvState.issue={title:'',description:'',severity:'一般',files:[],error:''};cvRefresh();toast('问题已收到（原型演示）');}
function cvValidate(){const cvFlags={'cv-sign':!cvState.signed&&cvState.read&&!cvOffline(),'cv-agree':!cvState.decision&&cvState.changeRead&&!cvOffline(),'cv-disagree':!cvState.decision&&cvValid(cvState.changeReason,10,2000)&&!cvOffline(),'cv-accept':cvAcceptReady(),'cv-issue':cvIssueReady()};cvFiles.forEach((cvF,cvIndex)=>{cvFlags['cv-post-'+cvIndex]=cvCanPost(cvIndex);});Object.entries(cvFlags).forEach(([cvId,cvReady])=>{const cvEl=document.getElementById(cvId);if(cvEl)cvEl.disabled=!cvReady;});const cvHint=document.getElementById('cv-accept-hint');if(cvHint)cvHint.textContent=`将接受 ${cvState.choices.filter(cvChoice=>cvChoice==='接受').length} 项、不接受 ${cvState.choices.filter(cvChoice=>cvChoice==='不接受').length} 项。`+(cvAcceptReady()?'可以提交。':'请逐项选择、补齐拒收类别与原因、签署姓名并确认清单；离线时不可提交。');}
window.CLIENT_PAGES={todo:cvTodo,project:cvProject,baseline:cvBaseline,changes:cvChangesPage,change:cvChange,deliveries:cvDeliveries,delivery:cvDelivery,previews:cvPreviews,feedback:cvFeedback};
/* 保留团队渲染器；主文件亦可直接根据 VIEWER 调用 CLIENT_PAGES。 */
Object.entries(window.CLIENT_PAGES).forEach(([cvKey,cvRender])=>{const cvTeam=PAGES[cvKey];PAGES[cvKey]=cvArg=>typeof VIEWER!=='undefined'&&VIEWER==='client'?cvRender(cvArg):cvTeam?cvTeam(cvArg):cvMissing();});
Object.assign(TITLES,{todo:'待办',project:'项目概览',baseline:'需求确认单',changes:'变更',change:'变更影响确认',deliveries:'交付与验收',delivery:'交付验收',previews:'预览与产物',feedback:'问题反馈'});
Object.assign(NAVPARENT,{todo:null,project:null,baseline:'project',changes:'project',change:'changes',deliveries:'project',delivery:'deliveries',previews:'project',feedback:'project'});
window.addEventListener('online',cvValidate);
window.addEventListener('offline',cvValidate);
